python3 << 'EOF'
from docx import Document
import json
import re

# Load employee data
with open('employee_data.json', 'r') as f:
    data = json.load(f)

# Load the template
doc = Document('offer_letter_template.docx')

def replace_placeholders(text, data):
    # Handle conditional relocation section
    if data.get('RELOCATION_PACKAGE', '').lower() == 'yes':
        # Keep content, remove markers
        text = text.replace('{{IF_RELOCATION}}', '')
        text = text.replace('{{END_IF_RELOCATION}}', '')
    else:
        # Remove the entire conditional section
        text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text, flags=re.DOTALL)

    # Replace all placeholders
    for key, value in data.items():
        placeholder = '{{' + key + '}}'
        text = text.replace(placeholder, str(value))

    return text

# Process paragraphs
for para in doc.paragraphs:
    if any('{{' in run.text for run in para.runs):
        # Get full paragraph text
        full_text = para.text
        new_text = replace_placeholders(full_text, data)

        # Clear existing runs and set new text
        for i, run in enumerate(para.runs):
            if i == 0:
                run.text = new_text
            else:
                run.text = ''
    elif '{{' in para.text:
        # Handle case where text isn't in runs
        para.text = replace_placeholders(para.text, data)

# Process tables if any
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                if '{{' in para.text:
                    full_text = para.text
                    new_text = replace_placeholders(full_text, data)
                    for i, run in enumerate(para.runs):
                        if i == 0:
                            run.text = new_text
                        else:
                            run.text = ''

# Save the filled document
doc.save('/root/offer_letter_filled.docx')
print("Offer letter saved successfully!")
EOF
